		__recover_inline_status(inode, node_page);

	/* get rdev by using inline_info */
	__get_inode_rdev(inode, ri);

	err = __written_first_block(sbi, ri);
	if (err < 0) {
		f2fs_put_page(node_page, 1);
		return err;
	}
	if (!err)
		set_inode_flag(inode, FI_FIRST_BLOCK_WRITTEN);

